(function(root){'use strict';
const blueprints=[{id:'trend',name:'趋势港',strategy:'趋势决策',partner:'趋势交易员',icon:'◈',color:'#90bfea',description:'板块已经涨出方向时跟进；对应“全额买入”。',dailyIncome:180},{id:'value',name:'价值街',strategy:'价值决策',partner:'价值投资员',icon:'◇',color:'#d6b785',description:'股票跌下来后先小额试买；对应“小额试仓”。',dailyIncome:150},{id:'defense',name:'防守园',strategy:'防守决策',partner:'风险管理师',icon:'⬡',color:'#91d8c1',description:'看不清时先保留现金；对应“暂不买入”。',dailyIncome:120},{id:'research',name:'研究院',strategy:'研究决策',partner:'量化研究员',icon:'✦',color:'#a9a0e8',description:'先核对数据再决定；对应“先查数据”。',dailyIncome:140}];
const factors=[{id:'momentum',difficulty:'R',concept:'动量因子',industry:'trend',name:'趋势·动量木材',icon:'▤',label:'趋势港专属材料',description:'给趋势港使用；行情延续时加强，反转时可能失效。'},{id:'lowvol',difficulty:'R',concept:'低波动因子',industry:'defense',name:'防守·低波钢材',icon:'▥',label:'防守园专属材料',description:'给防守园使用；降低波动但不保证赚钱。'},{id:'value',difficulty:'SR',concept:'估值因子',industry:'value',name:'价值·估值玻璃',icon:'▧',label:'价值街专属材料',description:'给价值街使用；价格便宜也可能继续下跌。'},{id:'volume',difficulty:'SSR',concept:'量价验证',industry:'research',name:'研究·量能铜线',icon:'⌁',label:'研究院专属材料',description:'给研究院使用；帮助核对消息与成交线索。'}];
function init(s){if(!s.city)s.city={version:2,cycle:0,blueprints:['trend'],materials:{momentum:2,lowvol:2,value:1,volume:1},districts:[],ledger:[],draws:[],drawn:{},pending:null,feedback:null};s.city.version=2;s.city.feedback??=null;return s.city;}
function gameDay(s){return Math.min(Game.CONFIG.days,Math.floor(s.round/Game.CONFIG.roundsPerDay)+1);}
function cycledToday(s){const day=gameDay(s),season=s.season||1;return init(s).ledger.some(x=>(x.gameDay||0)===day&&(x.season||1)===season);}
function draw(s,pool){const c=init(s),day=gameDay(s),season=s.season||1,key=pool+'-season-'+season+'-day-'+day;if(c.drawn[key])throw Error('今天已经抽过这类卡了，明天再来');c.drawn[key]=true;let item;if(pool==='strategy'){const available=blueprints.filter(b=>!c.blueprints.includes(b.id));item=available[Math.floor(Game.rand(s.seed+season*101+day*31+782)*available.length)];if(item)c.blueprints.push(item.id);else{c.materials.lowvol++;item={name:'蓝图已齐全 · 补充低波钢材'};}}else if(pool==='factor'){const f=factors[Math.floor(Game.rand(s.seed+season*101+day*37+521)*4)];c.materials[f.id]+=2;item={name:f.name+' × 2'};}else throw Error('未知卡池');const roll=Game.rand(s.seed+season*101+day*97+(pool==='strategy'?11:23)),rarity=roll<.5?'R':roll<.85?'SR':'SSR';c.draws.push({season,day,pool,item:item.name,rarity});return item.name;}
function build(s,id,factorIds,budget){const c=init(s);if(!c.blueprints.includes(id)||c.districts.some(d=>d.id===id))throw Error('蓝图不可用或区域已建成');if(!s.evidence.some(e=>e.dimension==='attribute'&&e.value===id&&e.source!=='city_build'))throw Error('先在决策中获得一次同类属性，才能建设这个产业');if(!Number.isInteger(budget)||budget<100||budget>5000)throw Error('预算须为100–5000整数游戏币');if(factorIds.length<1||factorIds.length>2||new Set(factorIds).size!==factorIds.length)throw Error('选择1–2种不同材料');for(const f of factorIds)if(!factors.some(x=>x.id===f)||!c.materials[f])throw Error('材料不足');for(const f of factorIds)c.materials[f]--;const district={id,factors:[...factorIds],budget,development:12,stability:100,last:null};c.districts.push(district);c.pending=null;const blueprint=blueprints.find(b=>b.id===id),materialNames=factorIds.map(id=>factors.find(f=>f.id===id).name);c.feedback={kind:'build',title:blueprint.name+'建成',text:blueprint.strategy+' +1。你的同类决策解锁了这个产业。'};Game.evidence(s,'construction',id+'|'+factorIds.join('+')+'|'+(budget<=1000?'small':budget<=3000?'medium':'large'),'observed_action','during',false,'city-'+id);Game.evidence(s,'attribute',id,'city_build','during',false,'city-'+id);return district;}
function refit(s,id,ids,budget){const c=init(s),d=c.districts.find(d=>d.id===id);if(!d)throw Error('区域不存在');if(!Number.isInteger(budget)||budget<100||budget>5000)throw Error('预算须为100–5000整数');if(ids.length<1||ids.length>2||new Set(ids).size!==ids.length)throw Error('选择1–2种不同材料');for(const f of ids)if(!factors.some(x=>x.id===f)||(c.materials[f]||0)+(d.factors.includes(f)?1:0)<1)throw Error('材料不足');for(const f of d.factors)c.materials[f]++;for(const f of ids)c.materials[f]--;d.factors=[...ids];d.budget=budget;c.pending=null;const blueprint=blueprints.find(b=>b.id===id);c.feedback={kind:'refit',title:blueprint.name+'已调整',text:'新材料：'+ids.map(id=>factors.find(f=>f.id===id).name).join('、')+'；每日建设预算 '+budget+' 游戏币。下次领取建设收益时显示调整效果。'};Game.evidence(s,'construction',id+'|'+ids.join('+')+'|'+(budget<=1000?'small':budget<=3000?'medium':'large'),'observed_action','during',false);}
function market(seed,cycle){const x=Game.rand((seed+cycle*7919+95671)>>>0);return {seed:(seed+cycle*7919+95671)>>>0,regime:x<.34?'上行':x<.67?'震荡':'下行',basisPoints:Math.floor(x*1601)-800};}
function returns(d,m){const bp=blueprints.find(b=>b.id===d.id),level=Math.max(1,Math.floor((d.development||0)/25)+1),gross=bp.dailyIncome+(level-1)*20;return {bp:0,turnover:0,fee:0,gross,credit:gross,fixed:true};}
function draft(s){const c=init(s),day=gameDay(s),season=s.season||1;if(cycledToday(s))throw Error('今天已经领取过建设收益；完成今天 3 轮决策后，明天可再次领取');if(!c.districts.length)throw Error('先建设至少一个策略区域');const amount=c.districts.reduce((n,d)=>n+returns(d,{}).gross,0);return {cycle:c.cycle,season,gameDay:day,key:s.id+'-city-season-'+season+'-day-'+day,amount,fees:0,config:JSON.stringify(c.districts.map(d=>({id:d.id,factors:d.factors,budget:d.budget,development:d.development}))),rule:'city-2.0-fixed-income'};}
function settle(s,a){const c=init(s),prior=c.ledger.find(e=>e.idempotencyKey===a.key);if(prior)return prior;const valid=draft(s);if(a.key!==valid.key||a.config!==valid.config||a.cycle!==valid.cycle||a.gameDay!==valid.gameDay||a.season!==valid.season)throw Error('城市方案已变化，请重新确认');const m={regime:'固定经营',basisPoints:0,seed:0},before=s.balance,details=c.districts.map(d=>{const r=returns(d,m),delta=r.gross;d.development=Math.min(100,d.development+8);d.stability=100;d.last={...r,delta,cycle:c.cycle};return {id:d.id,budget:d.budget,factors:[...d.factors],development:d.development,stability:d.stability,...d.last};}),delta=details.reduce((n,d)=>n+d.delta,0);s.balance+=delta;const entry={idempotencyKey:a.key,cycle:c.cycle,season:a.season,gameDay:a.gameDay,market:m,rule:a.rule,proposal:a,details,balanceBefore:before,balanceAfter:s.balance,delta};c.ledger.push(entry);c.cycle++;c.pending=null;c.feedback={kind:'market',title:'第 '+a.season+' 赛季第 '+a.gameDay+' 天建设收益',text:'城区建设固定经营收益 +'+delta+' 游戏币。'+details.map(d=>blueprints.find(b=>b.id===d.id).name+' +'+d.delta).join('；')};Game.evidence(s,'city','第'+a.season+'赛季第'+a.gameDay+'天固定建设收益：'+details.map(d=>d.id+'+'+d.delta).join('；'),'observed_action','during',false,'city-s'+a.season+'-d'+a.gameDay);return entry;}
const api={blueprints,factors,init,gameDay,cycledToday,draw,build,refit,market,returns,draft,settle};if(typeof module!=='undefined')module.exports=api;else root.GameCity=api;
})(typeof window==='undefined'?globalThis:window);
